    let mut chars = value.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

fn validate_type(ty: &ModelType, names: &BTreeSet<&str>) -> Result<(), GenerationError> {
    match ty {
        ModelType::Named(name) if !names.contains(name.as_str()) => {
            Err(GenerationError::UnknownModel(name.clone()))
        }
        ModelType::Sequence(inner) | ModelType::Dictionary(inner) => validate_type(inner, names),
        _ => Ok(()),
    }
}

