#[path = "solution.rs"]
mod solution;

use solution::{emit_rust_models, GenerationError, Model, ModelType, Property};

fn property(name: &str, model_type: ModelType, required: bool) -> Property {
    Property { name: name.to_string(), model_type, required }
}

fn model(name: &str, properties: Vec<Property>) -> Model {
    Model { name: name.to_string(), properties }
}

#[test]
fn empty_input_emits_empty_string() {
    assert_eq!(emit_rust_models(&[]).unwrap(), "");
}

#[test]
fn emits_all_type_mappings_optional_wrappers_and_exact_formatting() {
    let models = vec![
        model("User", vec![
            property("name", ModelType::Text, true),
            property("age", ModelType::Integer, false),
            property("ratio", ModelType::Decimal, true),
            property("active", ModelType::Flag, true),
            property("aliases", ModelType::Sequence(Box::new(ModelType::Text)), false),
            property(
                "lookup",
                ModelType::Dictionary(Box::new(ModelType::Sequence(Box::new(ModelType::Named("User".to_string()))))),
                true,
            ),
        ]),
        model("_Empty2", vec![]),
    ];

    let generated = emit_rust_models(&models).unwrap();
    let expected = "#[derive(Clone, Debug, PartialEq)]\npub struct User {\n    pub name: String,\n    pub age: Option<i64>,\n    pub ratio: f64,\n    pub active: bool,\n    pub aliases: Option<Vec<String>>,\n    pub lookup: std::collections::BTreeMap<String, Vec<User>>,\n}\n\n#[derive(Clone, Debug, PartialEq)]\npub struct _Empty2 {\n}\n";
    assert_eq!(generated, expected);
}

#[test]
fn forward_named_references_are_valid_and_input_order_is_preserved() {
    let models = vec![
        model("First", vec![property("second", ModelType::Named("Second".to_string()), true)]),
        model("Second", vec![property("value", ModelType::Text, true)]),
    ];
    let output = emit_rust_models(&models).unwrap();
    assert!(output.starts_with("#[derive(Clone, Debug, PartialEq)]\npub struct First"));
    assert!(output.contains("    pub second: Second,"));
    assert!(output.find("pub struct First").unwrap() < output.find("pub struct Second").unwrap());
}

#[test]
fn accepts_identifier_boundaries_and_rejects_invalid_model_names() {
    let valid = vec![model("_", vec![property("a0_Z", ModelType::Flag, true)])];
    assert!(emit_rust_models(&valid).is_ok());

    for invalid in ["", "9Model", "has-dash", "naïve", "with space"] {
        let models = vec![model(invalid, vec![])];
        assert_eq!(
            emit_rust_models(&models),
            Err(GenerationError::InvalidIdentifier(invalid.to_string()))
        );
    }
}

#[test]
fn rejects_invalid_property_names_in_property_order() {
    let models = vec![model("Valid", vec![
        property("good", ModelType::Text, true),
        property("2bad", ModelType::Text, true),
        property("also-bad", ModelType::Text, true),
    ])];
    assert_eq!(
        emit_rust_models(&models),
        Err(GenerationError::InvalidIdentifier("2bad".to_string()))
    );
}

#[test]
fn duplicate_models_report_the_first_repeated_declaration() {
    let models = vec![model("A", vec![]), model("B", vec![]), model("A", vec![])];
    assert_eq!(
        emit_rust_models(&models),
        Err(GenerationError::DuplicateModel("A".to_string()))
    );
}

#[test]
fn duplicate_properties_are_scoped_to_each_model() {
    let models = vec![
        model("A", vec![
            property("same", ModelType::Text, true),
            property("same", ModelType::Integer, true),
        ]),
        model("B", vec![property("same", ModelType::Text, true)]),
    ];
    assert_eq!(
        emit_rust_models(&models),
        Err(GenerationError::DuplicateProperty {
            model: "A".to_string(),
            property: "same".to_string(),
        })
    );
}

#[test]
fn unknown_models_are_found_inside_nested_types() {
    let models = vec![model("Container", vec![property(
        "items",
        ModelType::Sequence(Box::new(ModelType::Dictionary(Box::new(ModelType::Named("Missing".to_string()))))),
        true,
    )])];
    assert_eq!(
        emit_rust_models(&models),
        Err(GenerationError::UnknownModel("Missing".to_string()))
    );
}

#[test]
fn validation_errors_follow_model_and_property_input_order() {
    let models = vec![
        model("First", vec![property("reference", ModelType::Named("Absent".to_string()), true)]),
        model("Second", vec![property("bad-name", ModelType::Text, true)]),
    ];
    assert_eq!(
        emit_rust_models(&models),
        Err(GenerationError::UnknownModel("Absent".to_string()))
    );
}

#[test]
fn generation_does_not_mutate_inputs() {
    let models = vec![model("Item", vec![property(
        "values",
        ModelType::Sequence(Box::new(ModelType::Integer)),
        false,
    )])];
    let before = models.clone();
    let _ = emit_rust_models(&models).unwrap();
    assert_eq!(models, before);
}

